574	    @SafeVarargs
575	    private List<Future<Integer>> runConcurrent(Callable<Integer>... tasks) throws Exception {
576	        ExecutorService pool = Executors.newFixedThreadPool(tasks.length);
577	        CyclicBarrier barrier = new CyclicBarrier(tasks.length);
578	        List<Future<Integer>> futures = new ArrayList<>();
579	        for (Callable<Integer> task : tasks) {
580	            futures.add(pool.submit(() -> {
581	                barrier.await(10, TimeUnit.SECONDS);
582	                return task.call();
583	            }));
584	        }
585	        pool.shutdown();
586	        assertTrue(pool.awaitTermination(30, TimeUnit.SECONDS));
587	        return futures;
588	    }
