565	    /**
566	     * 让批次走完 检验 PASS + 双角色批准 进入 RELEASED。
567	     */
568	    private void releaseBatch(String batchKey, String inspector) throws Exception {
569	        MvcResult history = mockMvc.perform(get("/api/batches/" + batchKey + "/history"))
570	                .andExpect(status().isOk()).andReturn();
571	        JsonNode node = objectMapper.readTree(history.getResponse().getContentAsString());
572	        for (JsonNode item : node.path("batch").path("requiredTests")) {
573	            submitTest(batchKey, item.asText(), "PASS", inspector, 201);
574	        }
575	        approve(batchKey, "qa-" + unique(), "QUALITY", "CK-AQ-" + unique(), 201);
576	        approve(batchKey, "ops-" + unique(), "OPERATIONS", "CK-AO-" + unique(), 201);
