579	    private void submitTest(String batchKey, String item, String result, String inspector,
580	                            int expected) throws Exception {
581	        mockMvc.perform(post("/api/batches/" + batchKey + "/tests")
582	                        .contentType(MediaType.APPLICATION_JSON)
583	                        .content(objectMapper.writeValueAsString(
584	                                new TestCmd("CK-T-" + unique(), "TK-" + unique(), item, result,
